// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const fs = require('node:fs');
const http = require('node:http');
const path = require('node:path');

/**
 * The Graph page in a real browser draws and lays out a representative graph within its budget: 5,000 nodes in
 * 500 ms and 50,000 in 5 s, measured from the moment the page hands the query's answer to the canvas (the
 * "graph-explorer:answer-shown" User Timing mark) to the first frame drawn after the layout worker's positions arrive.
 *
 * The page runs the built bundle (npm run build in tools/workbench) against a local stand-in for the Workbench's Graph
 * servlet, so the measurement is the browser's work alone: no RDF4J server, network or store is involved. Motion is
 * reduced, so the frame after the layout shows the final positions rather than the start of a transition.
 * GRAPH_PERFORMANCE_SLOWDOWN scales the budgets for a slower machine.
 */
const REPOSITORY_ROOT = path.resolve(__dirname, '..', '..');
const FRONTEND = path.join(REPOSITORY_ROOT, 'tools', 'workbench', 'target', 'frontend');
const FIXTURE = path.join(REPOSITORY_ROOT, 'tools', 'workbench', 'src', 'test', 'frontend', 'graph-explorer', 'fixtures',
    'representative-graph.mjs');
const BUNDLE = path.join(FRONTEND, 'scripts', 'graph-explorer', 'graph-explorer.mjs');
const DEFAULT_QUERY = 'SELECT ?source ?predicate ?target WHERE { ?source ?predicate ?target } LIMIT 100';
const IDENTITY = 'sha256:graph-scale-performance';
const EMPTY_ANSWER = JSON.stringify({ head: { vars: [] }, results: { bindings: [] } });
// A CI runner draws 5,000 nodes in 650-750 ms where a developer machine takes under 500: it gets twice the budget.
const SLOWDOWN = Number(process.env.GRAPH_PERFORMANCE_SLOWDOWN || (process.env.CI ? 2 : 1)) || 1;
const SIZES = [{ nodes: 5000, budgetMs: 500 }, { nodes: 50000, budgetMs: 5000 }];

const PAGE = `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Graph scale</title></head>
<body style="margin:0">
<div id="workbench-app" data-workbench-base-path="/rdf4j-workbench">
  <div id="workbench-page-surface" class="workbench-page-surface"><div id="outlet"><div data-graph-explorer-mount></div></div></div>
</div>
<script type="module">
  import "/rdf4j-workbench/scripts/graph-explorer/graph-explorer.mjs";
  window.workbench.graphExplorer.mount(document.getElementById("outlet"),
    { context: { basePath: "/rdf4j-workbench", repositoryId: "scale", serverIdentity: "${IDENTITY}" } });
</script>
</body>
</html>`;

const TYPES = { '.mjs': 'text/javascript', '.js': 'text/javascript', '.css': 'text/css', '.map': 'application/json' };

/** Records, in the page, when the answer is shown, when the layout ends and the next frame is drawn. */
function watchGraphScale() {
    const state = { busy: 0, layoutAt: 0, doneAt: 0 };
    // @ts-ignore
    window.__graphScale = state;
    new MutationObserver((records) => {
        for (const record of records) {
            const element = /** @type {Element} */ (record.target);
            if (record.attributeName === 'aria-busy' && element.classList.contains('large-graph-hint')) {
                if (element.getAttribute('aria-busy') === 'true') state.busy++;
                else if (state.busy && !state.layoutAt) state.layoutAt = performance.now();
            }
            if (record.attributeName === 'data-frames' && state.layoutAt && !state.doneAt) {
                state.doneAt = performance.now();
                const overlay = /** @type {HTMLElement} */ (element);
                Object.assign(state, { renderer: overlay.dataset.renderer, averageDrawMs: Number(overlay.dataset.averageDrawMs) });
            }
        }
    }).observe(document, { subtree: true, attributes: true, attributeFilter: ['aria-busy', 'data-frames'] });
}

let server;
let base = '';
const answers = new Map();
let answering = 0;

test.describe.configure({ mode: 'serial' });

test.beforeAll(async () => {
    if (!fs.existsSync(BUNDLE)) return;
    const { representativeResults } = await import(FIXTURE);
    for (const { nodes } of SIZES) answers.set(nodes, JSON.stringify(representativeResults(nodes)));
    server = http.createServer((request, response) => {
        const url = new URL(request.url || '/', 'http://localhost');
        if (url.pathname === '/scale.html') {
            response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
            response.end(PAGE);
        } else if (request.method === 'POST' && url.pathname === '/rdf4j-workbench/repositories/scale/graph') {
            const chunks = [];
            request.on('data', (chunk) => chunks.push(chunk));
            request.on('end', () => {
                const query = Buffer.concat(chunks).toString('utf8');
                response.writeHead(200, { 'content-type': 'application/sparql-results+json',
                    'x-workbench-server-identity': IDENTITY, 'cache-control': 'no-store' });
                // The page's own load query gets the graph; its label, type and count queries get nothing.
                response.end(query === DEFAULT_QUERY ? answers.get(answering) : EMPTY_ANSWER);
            });
        } else if (url.pathname.startsWith('/rdf4j-workbench/')) {
            const file = path.normalize(path.join(FRONTEND, url.pathname.slice('/rdf4j-workbench/'.length)));
            if (!file.startsWith(FRONTEND) || !fs.existsSync(file) || !fs.statSync(file).isFile()) {
                response.writeHead(404).end();
                return;
            }
            response.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' });
            fs.createReadStream(file).pipe(response);
        } else {
            response.writeHead(404).end();
        }
    });
    await new Promise((resolve) => server.listen(0, '127.0.0.1', () => resolve(undefined)));
    base = `http://127.0.0.1:${server.address().port}`;
});

test.afterAll(async () => {
    if (server) await new Promise((resolve) => server.close(() => resolve(undefined)));
});

for (const { nodes, budgetMs } of SIZES) {
    test(`the Graph page draws and lays out ${nodes.toLocaleString('en')} nodes within ${budgetMs.toLocaleString('en')} ms`,
        async ({ page, browserName }) => {
            test.skip(browserName !== 'chromium', 'the budgets are set for Chromium');
            test.skip(!fs.existsSync(BUNDLE), 'build the Workbench front end first (npm run build in tools/workbench)');
            test.setTimeout(180000);
            answering = nodes;
            const errors = [];
            page.on('pageerror', (error) => errors.push(error.message));
            await page.emulateMedia({ reducedMotion: 'reduce' });
            await page.setViewportSize({ width: 1440, height: 900 });
            await page.addInitScript(watchGraphScale);
            await page.goto(`${base}/scale.html`);

            await page.getByRole('button', { name: 'Load 100 statements' }).click();
            const handle = await page.waitForFunction(() => {
                // @ts-ignore
                const state = window.__graphScale;
                return state.doneAt ? state : null;
            }, null, { timeout: 150000, polling: 100 });
            const state = await handle.jsonValue();
            const timing = await page.evaluate(() => {
                const shown = performance.getEntriesByName('graph-explorer:answer-shown').at(-1);
                return shown ? { shownAt: shown.startTime, detail: /** @type {PerformanceMark} */ (shown).detail } : null;
            });

            expect(errors).toEqual([]);
            expect(timing, 'the page marked the answer it showed').not.toBeNull();
            expect(timing.detail.nodes).toBeGreaterThan(nodes);
            await expect(page.locator('.large-graph-interactive')).toHaveAttribute('aria-label',
                new RegExp(`with ${nodes} nodes`));
            const layoutMs = state.layoutAt - timing.shownAt;
            const totalMs = state.doneAt - timing.shownAt;
            test.info().annotations.push({ type: 'timing',
                description: `${nodes} nodes: layout ${Math.round(layoutMs)} ms, laid-out frame ${Math.round(totalMs)} ms, `
                    + `${state.renderer} frames ~${state.averageDrawMs} ms` });
            console.log(test.info().annotations.at(-1).description);
            expect(state.renderer).toBe('webgl');
            expect(totalMs, `answer shown to laid-out frame for ${nodes} nodes`).toBeLessThan(budgetMs * SLOWDOWN);
        });
}
